import "../App.css";
import { useRedirectUnknown, matchPath, useLocation } from "../shared/router/index.ts";
import { SessionsPage } from "../features/sessions/SessionsPage.tsx";

const KNOWN_ROUTES = ["/sessions", "/sessions/:id"] as const;

function App() {
  const { pathname } = useLocation();
  useRedirectUnknown(KNOWN_ROUTES, "/sessions");

  const known = KNOWN_ROUTES.some((pattern) => matchPath(pattern, pathname) !== null);
  // В S6 /sessions/:id показывает список без деталей (диалог — S7).
  return known ? <SessionsPage /> : null;
}

export default App
import { useEffect, useMemo, useSyncExternalStore } from "react";

// Тонкий слой History API. Доменных имён параметров не знает.

const NAVIGATE_EVENT = "app:navigate";

export interface NavigateOptions {
  replace?: boolean;
  state?: unknown;
}

export interface RouterLocation {
  pathname: string;
  search: string;
}

export function navigate(to: string, options: NavigateOptions = {}): void {
  if (options.replace) {
    window.history.replaceState(options.state ?? null, "", to);
  } else {
    window.history.pushState(options.state ?? null, "", to);
  }
  window.dispatchEvent(new Event(NAVIGATE_EVENT));
}

/** Состояние текущей записи истории (флаг «из приложения / из списка» задаёт вызывающий код). */
export function readHistoryState(): unknown {
  return window.history.state;
}

function subscribe(onChange: () => void): () => void {
  window.addEventListener("popstate", onChange);
  window.addEventListener(NAVIGATE_EVENT, onChange);
  return () => {
    window.removeEventListener("popstate", onChange);
    window.removeEventListener(NAVIGATE_EVENT, onChange);
  };
}

function getSnapshot(): string {
  return window.location.pathname + window.location.search;
}

/** Текущие path и search с подпиской на popstate и собственные навигации. */
export function useLocation(): RouterLocation {
  const snapshot = useSyncExternalStore(subscribe, getSnapshot);
  return useMemo(() => {
    const i = snapshot.indexOf("?");
    return i === -1
      ? { pathname: snapshot, search: "" }
      : { pathname: snapshot.slice(0, i), search: snapshot.slice(i) };
  }, [snapshot]);
}

function normalizePath(pathname: string): string {
  return pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
}

/** Сопоставление пути с шаблоном вида `/sessions/:id`. `null`, если путь не подходит. */
export function matchPath(pattern: string, pathname: string): Record<string, string> | null {
  const want = normalizePath(pattern).split("/");
  const have = normalizePath(pathname).split("/");
  if (want.length !== have.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < want.length; i += 1) {
    const w = want[i];
    const h = have[i];
    if (w.startsWith(":")) {
      if (h === "") return null;
      try {
        params[w.slice(1)] = decodeURIComponent(h);
      } catch {
        return null;
      }
    } else if (w !== h) {
      return null;
    }
  }
  return params;
}

export function getSearchParam(search: string, name: string): string | null {
  return new URLSearchParams(search).get(name);
}

/**
 * Возвращает новый search (`?a=b` или пустую строку). `null`/`undefined`/`""` удаляют параметр,
 * остальные параметры сохраняются нетронутыми.
 */
export function updateSearch(
  search: string,
  updates: Record<string, string | null | undefined>,
): string {
  const params = new URLSearchParams(search);
  for (const [name, value] of Object.entries(updates)) {
    if (value === null || value === undefined || value === "") {
      params.delete(name);
    } else {
      params.set(name, value);
    }
  }
  const next = params.toString();
  return next ? `?${next}` : "";
}

/** Неизвестный путь -> `replace` на `fallback` с сохранением search. */
export function useRedirectUnknown(knownPatterns: readonly string[], fallback: string): void {
  const { pathname, search } = useLocation();
  const known = knownPatterns.some((pattern) => matchPath(pattern, pathname) !== null);
  useEffect(() => {
    if (!known) navigate(`${fallback}${search}`, { replace: true });
  }, [known, fallback, search]);
}
import { cleanup } from "@testing-library/react";
import { afterAll, afterEach, beforeAll, beforeEach, vi } from "vitest";
import { setMockLatency } from "../mocks/handlers.ts";
import { server } from "../mocks/node.ts";
import { resetStore } from "../mocks/store.ts";
import { FROZEN_NOW } from "./constants.ts";

// jsdom 31 не реализует HTMLDialogElement.showModal/close (проверено запуском): минимальный полифил.
// Он не моделирует фокус, инертность фона и Esc; это проверяется в browser-verify.
if (typeof HTMLDialogElement.prototype.showModal !== "function") {
  HTMLDialogElement.prototype.showModal = function showModal(this: HTMLDialogElement): void {
    this.setAttribute("open", "");
  };
}
if (typeof HTMLDialogElement.prototype.close !== "function") {
  HTMLDialogElement.prototype.close = function close(
    this: HTMLDialogElement,
    returnValue?: string,
  ): void {
    if (!this.hasAttribute("open")) return;
    this.removeAttribute("open");
    if (returnValue !== undefined) this.returnValue = returnValue;
    this.dispatchEvent(new Event("close"));
  };
}

beforeAll(() => {
  server.listen({ onUnhandledRequest: "error" });
});

beforeEach(() => {
  // Подменяем только Date: таймеры, MSW, userEvent и debounce работают по-настоящему.
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(FROZEN_NOW);
  setMockLatency(0);
  resetStore();
});

afterEach(() => {
  cleanup();
  server.resetHandlers();
  vi.useRealTimers();
  window.history.replaceState(null, "", "/");
});

afterAll(() => {
  server.close();
});
import { render, type RenderResult } from "@testing-library/react";
import userEvent, { type UserEvent } from "@testing-library/user-event";
import type { ReactElement } from "react";

/** Рендер с заданным начальным URL; userEvent привязан к реальным таймерам. */
export function renderAt(
  ui: ReactElement,
  url = "/sessions",
): RenderResult & { user: UserEvent } {
  window.history.replaceState(null, "", url);
  const user = userEvent.setup();
  return { user, ...render(ui) };
}
/** Замороженный «сейчас» для всех тестов. */
export const FROZEN_NOW = "2026-08-01T10:00:00Z";
import type { MouseEvent } from "react";
import type { SessionSummary } from "../../shared/api/types.ts";
import { formatListDateTime } from "../../shared/lib/datetime.ts";
import { navigate } from "../../shared/router/index.ts";
import { copy, TYPE_LABELS } from "./copy.ts";
import { StatusBadge } from "./StatusBadge.tsx";

interface SessionRowProps {
  session: SessionSummary;
  /** Текущий search (с `?`), сохраняется в ссылке на детали. */
  search: string;
}

function isPlainLeftClick(event: MouseEvent<HTMLAnchorElement>): boolean {
  return (
    event.button === 0 &&
    !event.defaultPrevented &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey
  );
}

export function SessionRow({ session, search }: SessionRowProps) {
  const href = `/sessions/${encodeURIComponent(session.id)}${search}`;

  function handleClick(event: MouseEvent<HTMLAnchorElement>): void {
    // Модификаторы и средняя кнопка остаются за браузером (новая вкладка).
    if (!isPlainLeftClick(event)) return;
    event.preventDefault();
    navigate(href, { state: { fromList: true } });
  }

  return (
    <li className="session-row">
      <div className="cell cell-session">
        <a className="session-link" href={href} onClick={handleClick}>
          {session.title}
        </a>
        <span className="muted">
          {TYPE_LABELS[session.type]}
          {" · "}
          <span className="visually-hidden">{copy.sr.location}</span>
          {session.location.name}
        </span>
      </div>
      <div className="cell cell-start">
        <span>
          <span className="visually-hidden">{copy.sr.starts}</span>
          {formatListDateTime(session.startsAt)}
        </span>
        <span className="muted small">
          <span className="visually-hidden">{copy.sr.duration}</span>
          {copy.durationMinutes(session.durationMinutes)}
        </span>
      </div>
      <div className="cell cell-coach">
        <span className="visually-hidden">{copy.sr.coach}</span>
        {session.coach.name}
      </div>
      <div className="cell cell-capacity">
        <span className="visually-hidden">
          {copy.sr.capacity(session.bookedCount, session.capacity)}
        </span>
        <span aria-hidden="true">
          {session.bookedCount} / {session.capacity}
        </span>
      </div>
      <div className="cell cell-status">
        <span className="visually-hidden">{copy.sr.status}</span>
        <StatusBadge status={session.status} />
      </div>
    </li>
  );
}
import { useEffect, useRef, useState, type ChangeEvent } from "react";
import { SESSION_STATUSES, type SessionStatus } from "../../shared/api/types.ts";
import { navigate, readHistoryState, useLocation } from "../../shared/router/index.ts";
import { copy, STATUS_LABELS } from "./copy.ts";
import { clearFilters, hasActiveFilters, readFilters, writeFilters, type FilterUpdate } from "./filters.ts";
import { LiveStatus } from "./LiveStatus.tsx";
import { SessionRow } from "./SessionRow.tsx";
import { useSessions } from "./useSessions.ts";

/** Пауза после последнего символа перед записью поиска в URL. */
export const SEARCH_DEBOUNCE_MS = 300;

const SKELETON_ROWS = 5;

interface SessionsPageProps {
  /** В S6 форма создания не реализована: без обработчика кнопка ничего не делает. */
  onCreateSession?: () => void;
}

function isStatus(value: string): value is SessionStatus {
  return (SESSION_STATUSES as readonly string[]).includes(value);
}

export function SessionsPage({ onCreateSession }: SessionsPageProps) {
  const { pathname, search } = useLocation();
  const filters = readFilters(search);
  const active = hasActiveFilters(filters);
  const { status, data, error, isRefreshing, retry } = useSessions(filters);

  // Локальное transient-значение поля; в URL уходит с debounce. Внешнее изменение URL
  // (Назад, сброс) синхронизируется в поле во время рендера.
  const [text, setText] = useState(filters.query);
  const [seenQuery, setSeenQuery] = useState(filters.query);
  if (seenQuery !== filters.query) {
    setSeenQuery(filters.query);
    if (filters.query !== text.trim()) setText(filters.query);
  }
  const [justCleared, setJustCleared] = useState(false);

  const searchInput = useRef<HTMLInputElement>(null);
  const timer = useRef<number | undefined>(undefined);
  const latest = useRef({ pathname, search });
  useEffect(() => {
    latest.current = { pathname, search };
  });
  useEffect(() => () => window.clearTimeout(timer.current), []);

  function replaceFilters(next: (search: string) => string): void {
    const current = latest.current;
    const nextSearch = next(current.search);
    if (nextSearch === current.search) return;
    navigate(`${current.pathname}${nextSearch}`, { replace: true, state: readHistoryState() });
  }

  function writeUpdate(update: FilterUpdate): void {
    replaceFilters((s) => writeFilters(s, update));
  }

  function handleSearchChange(event: ChangeEvent<HTMLInputElement>): void {
    const value = event.target.value;
    setText(value);
    setJustCleared(false);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => writeUpdate({ query: value }), SEARCH_DEBOUNCE_MS);
  }

  function handleStatusChange(event: ChangeEvent<HTMLSelectElement>): void {
    const value = event.target.value;
    setJustCleared(false);
    writeUpdate({ status: isStatus(value) ? value : "" });
  }

  function handleClear(): void {
    window.clearTimeout(timer.current);
    setText("");
    setJustCleared(true);
    // Фокус переносится до того, как кнопка исчезнет вместе с фильтрами.
    searchInput.current?.focus();
    replaceFilters(clearFilters);
  }

  const total = data?.meta.total ?? 0;
  const rows = data?.data ?? [];

  let liveMessage = "";
  if (status === "loading") {
    liveMessage = copy.loading;
  } else if (status === "success") {
    if (rows.length === 0) {
      liveMessage = active ? copy.noMatchTitle : copy.emptyTitle;
    } else if (justCleared) {
      liveMessage = copy.filtersCleared(copy.sessionsCount(total));
    } else {
      liveMessage = active ? copy.matchCount(total) : copy.sessionsCount(total);
    }
  }

  return (
    <main className="page">
      <header className="page-header">
        <h1>{copy.pageTitle}</h1>
        <button type="button" className="button button-primary" onClick={onCreateSession}>
          {copy.createSession}
        </button>
      </header>

      <div className="toolbar">
        <div className="toolbar-search">
          <label htmlFor="sessions-search" className="visually-hidden">
            {copy.searchLabel}
          </label>
          <input
            ref={searchInput}
            id="sessions-search"
            name="query"
            type="search"
            autoComplete="off"
            spellCheck={false}
            placeholder={copy.searchPlaceholder}
            value={text}
            onChange={handleSearchChange}
          />
        </div>
        <div className="toolbar-status">
          <label htmlFor="sessions-status" className="visually-hidden">
            {copy.statusLabel}
          </label>
          <select
            id="sessions-status"
            name="status"
            value={filters.status}
            onChange={handleStatusChange}
          >
            <option value="">{copy.allStatuses}</option>
            {SESSION_STATUSES.map((value) => (
              <option key={value} value={value}>
                {STATUS_LABELS[value]}
              </option>
            ))}
          </select>
        </div>
        {active ? (
          <button type="button" className="button button-secondary" onClick={handleClear}>
            {copy.clearFilters}
          </button>
        ) : null}
      </div>

      <section className="list-area" aria-busy={isRefreshing}>
        {status === "error" ? (
          <div role="alert" className="state-message">
            <h2>{copy.errorTitle}</h2>
            <p>{copy.errorBody(error)}</p>
            <button type="button" className="button button-primary" onClick={retry}>
              {copy.tryAgain}
            </button>
          </div>
        ) : null}

        {status === "loading" && data === null ? (
          <ul className="session-list" aria-hidden="true">
            {Array.from({ length: SKELETON_ROWS }, (_, i) => (
              <li key={i} className="session-row skeleton-row">
                <span className="skeleton-line" />
              </li>
            ))}
          </ul>
        ) : null}

        {data !== null && status !== "error" && rows.length === 0 && status === "success" ? (
          active ? (
            <div className="state-message">
              <h2>{copy.noMatchTitle}</h2>
              <p>{copy.noMatchBody(filters)}</p>
              <button type="button" className="button button-secondary" onClick={handleClear}>
                {copy.clearFilters}
              </button>
            </div>
          ) : (
            <div className="state-message">
              <h2>{copy.emptyTitle}</h2>
              <p>{copy.emptyBody}</p>
              <button type="button" className="button button-primary" onClick={onCreateSession}>
                {copy.createSession}
              </button>
            </div>
          )
        ) : null}

        {data !== null && status !== "error" && rows.length > 0 ? (
          <div className={isRefreshing ? "list-content is-refreshing" : "list-content"}>
            <p className="list-count">{copy.sessionsCount(total)}</p>
            <div className="session-list-head" aria-hidden="true">
              <span>Session</span>
              <span>Start</span>
              <span>Coach</span>
              <span>Capacity</span>
              <span>Status</span>
            </div>
            <ul className="session-list">
              {rows.map((session) => (
                <SessionRow key={session.id} session={session} search={search} />
              ))}
            </ul>
          </div>
        ) : null}
      </section>

      <LiveStatus message={liveMessage} />
    </main>
  );
}
import type { SessionStatus } from "../../shared/api/types.ts";
import { STATUS_LABELS } from "./copy.ts";

function Icon({ status }: { status: SessionStatus }) {
  const common = {
    width: 12,
    height: 12,
    viewBox: "0 0 12 12",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.6,
    "aria-hidden": true,
    focusable: false,
  } as const;
  switch (status) {
    case "scheduled":
      return (
        <svg {...common}>
          <rect x="1.5" y="2.5" width="9" height="8" rx="1" />
          <path d="M1.5 5h9M4 1v2.5M8 1v2.5" />
        </svg>
      );
    case "full":
      return (
        <svg {...common}>
          <circle cx="6" cy="6" r="4.5" fill="currentColor" />
        </svg>
      );
    case "cancelled":
      return (
        <svg {...common}>
          <path d="M2.5 2.5l7 7M9.5 2.5l-7 7" />
        </svg>
      );
    case "completed":
      return (
        <svg {...common}>
          <path d="M2 6.5l2.8 2.8L10 3.2" />
        </svg>
      );
  }
}

/** Статус не только цветом: форма-иконка (скрыта от скринридера) и видимый текст. */
export function StatusBadge({ status }: { status: SessionStatus }) {
  return (
    <span className={`status-badge status-${status}`}>
      <Icon status={status} />
      <span>{STATUS_LABELS[status]}</span>
    </span>
  );
}
import type { SessionStatus, SessionType } from "../../shared/api/types.ts";
import type { ClientError } from "../../shared/api/errors.ts";
import type { SessionFilters } from "./filters.ts";

// Тексты интерфейса фичи (английский, решение 3=B).

export const STATUS_LABELS: Record<SessionStatus, string> = {
  scheduled: "Scheduled",
  full: "Full",
  cancelled: "Cancelled",
  completed: "Completed",
};

export const TYPE_LABELS: Record<SessionType, string> = {
  training: "Training",
  camp: "Camp",
  private: "Private",
};

function plural(n: number, one: string, many: string): string {
  return `${n} ${n === 1 ? one : many}`;
}

export const copy = {
  pageTitle: "Training sessions",
  createSession: "Create session",
  searchLabel: "Search sessions",
  searchPlaceholder: "Title, coach, or location…",
  statusLabel: "Status",
  allStatuses: "All statuses",
  clearFilters: "Clear filters",
  loading: "Loading sessions…",
  emptyTitle: "No sessions yet",
  emptyBody: "Create the first training session to start building your schedule.",
  noMatchTitle: "No sessions match your filters",
  errorTitle: "Sessions couldn't be loaded",
  tryAgain: "Try again",

  sessionsCount: (n: number): string => plural(n, "session", "sessions"),
  matchCount: (n: number): string =>
    `${n} ${n === 1 ? "session matches" : "sessions match"} your filters`,
  filtersCleared: (countText: string): string => `Filters cleared. ${countText}.`,
  durationMinutes: (n: number): string => plural(n, "minute", "minutes"),

  noMatchBody: (filters: SessionFilters): string => {
    const status = filters.status === "" ? "" : STATUS_LABELS[filters.status];
    if (filters.query !== "" && status !== "") {
      return `Nothing found for “${filters.query}” with status ${status}. Try different keywords or clear the filters.`;
    }
    if (filters.query !== "") {
      return `Nothing found for “${filters.query}”. Try different keywords or clear the filters.`;
    }
    return `No ${status} sessions found. Clear the filters to see all sessions.`;
  },

  errorBody: (error: ClientError | null): string => {
    if (error?.kind === "network") return "Check your connection and try again.";
    if (error?.kind === "malformed") {
      return "The server sent an unexpected response. Try again in a moment.";
    }
    return "Your filters are kept. Try again in a moment.";
  },

  // Скрытые подписи для скринридера в строке списка.
  sr: {
    starts: "Starts: ",
    duration: "Duration: ",
    coach: "Coach: ",
    location: "Location: ",
    capacity: (booked: number, capacity: number): string =>
      `Capacity: ${booked} of ${capacity}`,
    status: "Status: ",
  },
} as const;
import { useCallback, useEffect, useState } from "react";
import { getSessions } from "../../shared/api/client.ts";
import type { ClientError } from "../../shared/api/errors.ts";
import type { SessionsResponse } from "../../shared/api/types.ts";
import type { SessionFilters } from "./filters.ts";

export type SessionsStatus = "idle" | "loading" | "success" | "error";

interface State {
  status: SessionsStatus;
  data: SessionsResponse | null;
  error: ClientError | null;
}

interface Settled {
  /** Ключ запроса, которому принадлежит результат. */
  key: string;
  data: SessionsResponse | null;
  error: ClientError | null;
}

export interface UseSessionsResult extends State {
  /** Идёт загрузка при уже имеющихся (прежних) данных: список приглушается. */
  isRefreshing: boolean;
  retry: () => void;
}

/**
 * Список сессий по фильтрам. Запрос отменяется при смене фильтров и размонтировании, устаревшие
 * ответы игнорируются. Прежние данные сохраняются на время `loading`. `reloadKey` — сигнал
 * принудительного обновления (после создания сессии). Состояние `loading` выводится при рендере
 * (ключ запроса не совпадает с ключом последнего результата), без setState в эффекте.
 */
export function useSessions(filters: SessionFilters, reloadKey = 0): UseSessionsResult {
  const [settled, setSettled] = useState<Settled | null>(null);
  const [attempt, setAttempt] = useState(0);
  const { query, status } = filters;
  const key = JSON.stringify([query, status, attempt, reloadKey]);

  useEffect(() => {
    const controller = new AbortController();
    void getSessions({ query, status }, { signal: controller.signal }).then((result) => {
      if (controller.signal.aborted) return;
      if (result.ok) {
        setSettled({ key, data: result.data, error: null });
      } else if (!result.cancelled) {
        setSettled({ key, data: null, error: result.error });
      }
    });
    return () => controller.abort();
  }, [key, query, status]);

  const retry = useCallback(() => setAttempt((n) => n + 1), []);

  if (settled !== null && settled.key === key) {
    return {
      status: settled.error === null ? "success" : "error",
      data: settled.data,
      error: settled.error,
      isRefreshing: false,
      retry,
    };
  }
  const previous = settled?.data ?? null;
  return { status: "loading", data: previous, error: null, isRefreshing: previous !== null, retry };
}

