import { SessionsPage } from "../features/sessions/SessionsPage.tsx";

const KNOWN_ROUTES = ["/sessions", "/sessions/:id"] as const;

function App() {
  const { pathname } = useLocation();
  useRedirectUnknown(KNOWN_ROUTES, "/sessions");

