/* Начальные стили списка (S6). Полный адаптив, контраст и доводка — S9. */

.page {
  display: block;
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--page-padding);
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.page-header h1 {
  font-size: 24px;
  line-height: 32px;
  font-weight: 700;
  min-width: 0;
}

.muted {
  color: var(--text-muted);
}

.small {
  font-size: 12px;
}

/* Кнопки */
.button {
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-weight: 600;
  cursor: pointer;
  touch-action: manipulation;
}

.button-primary {
  background: var(--primary);
  color: #ffffff;
}

.button-primary:hover {
  background: var(--primary-hover);
}

.button-secondary {
  background: var(--surface);
  border-color: var(--border);
  color: var(--text);
}

.button-secondary:hover {
  background: var(--surface-muted);
}

/* Панель инструментов */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 12px;
  margin-bottom: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.toolbar-search {
  flex: 1 1 280px;
  min-width: 0;
}

.toolbar input[type="search"],
.toolbar select {
  width: 100%;
  min-height: 40px;
  padding: 0 12px;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.toolbar input::placeholder {
  color: var(--text-muted);
  opacity: 1;
}

.toolbar-status {
  flex: 0 1 200px;
  min-width: 0;
}

/* Область списка */
.list-count {
  font-weight: 700;
  margin-bottom: 8px;
}

.list-content.is-refreshing {
  opacity: 0.55;
}

.session-list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.session-list-head,
.session-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 160px 160px 100px 120px;
  align-items: center;
  column-gap: 16px;
}

.session-list-head {
  padding: 0 16px 6px;
  font-size: 11px;
  line-height: 16px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--text-muted);
}

.session-row {
  position: relative;
  min-height: 72px;
  padding: 12px 16px;
}

.session-row + .session-row {
  border-top: 1px solid var(--border);
}

.session-row:hover {
  background: var(--surface-muted);
}

.cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  overflow-wrap: anywhere;
  font-variant-numeric: tabular-nums;
}

.cell-capacity {
  font-variant-numeric: tabular-nums;
}

.session-link {
  font-weight: 700;
  color: var(--text);
  text-decoration: none;
}

.session-link:hover,
.session-link:focus-visible {
  text-decoration: underline;
}

/* Растянутая область клика на всю строку */
.session-link::after {
  content: "";
  position: absolute;
  inset: 0;
}

/* Бейдж статуса: иконка и текст */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border-radius: var(--radius);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  align-self: flex-start;
}

.status-scheduled {
  color: var(--success);
  background: #ddf1e4;
}

.status-full {
  color: var(--warning);
  background: #fff0cf;
}

.status-cancelled {
  color: var(--danger);
  background: #fbe4e2;
}

.status-completed {
  color: var(--text-muted);
  background: var(--surface-muted);
}

/* Состояния: пусто, нет совпадений, ошибка */
.state-message {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  padding: 24px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow-wrap: anywhere;
}

.state-message h2 {
  font-size: 16px;
  line-height: 24px;
  font-weight: 700;
}

.state-message p {
  color: var(--text-muted);
}

.state-message .button {
  margin-top: 8px;
}

/* Скелетон первичной загрузки */
.skeleton-row {
  display: block;
}

.skeleton-line {
  display: block;
  height: 16px;
  width: 60%;
  background: var(--surface-muted);
  border-radius: var(--radius);
  animation: skeleton-pulse 1.2s ease-in-out infinite;
}

@keyframes skeleton-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-line {
    animation: none;
  }
}

/* Мобильный: строка становится стеком */
@media (max-width: 720px) {
  .session-list-head {
    display: none;
  }

  .toolbar-status {
    flex: 1 1 140px;
  }

  .session-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "status capacity"
      "session session"
      "start start"
      "coach coach";
    row-gap: 4px;
    min-height: 64px;
  }

  .cell-status {
    grid-area: status;
  }

  .cell-capacity {
    grid-area: capacity;
    text-align: right;
  }

  .cell-session {
    grid-area: session;
  }

  .cell-start {
    grid-area: start;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 4px 8px;
  }

  .cell-coach {
    grid-area: coach;
    color: var(--text-muted);
  }
}

@media (max-width: 420px) {
  .page-header {
    flex-direction: column;
    align-items: stretch;
  }
}
